        {
          "no": 1,
          "action": "The RBC sends a request to shorten the MA with a proposed shortened MA, a mode profile, and a list of balise groups for SH area.",
          "expected": "The OBU receives the request and checks the train front end position against the Indication supervision limit of the proposed MA."
        },
        {
          "no": 2,
          "action": "The OBU processes the request.",
          "expected": "The OBU accepts the request, adopts the proposed shortened MA as the new MA, stores the accompanying mode profile and the list of balise groups for SH area, and sends an acknowledgement to the RBC indicating acceptance."
        }
      ]
    },
    {
      "id": "TC-ETC-074-02",
      "title": "Rejection of MA shortening when train is in advance of Indication supervision limit",
      "covers": [
        "ETC-074"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "Level 2, communication session with RBC established, train running in a mode with valid MA. The current MA has an EOA/LOA. The train front end position is estimated to be in advance of the proposed shortened MA's Indication supervision limit (i.e., the train has already passed the point where the new MA would start supervising).",
      "test_inputs": "RBC sends a 'Request to shorten MA' message containing a proposed shortened MA with an EOA closer to the train than the current EOA, including a mode profile and a list of balise groups for SH area.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "The RBC sends a request to shorten the MA with a proposed shortened MA, a mode profile, and a list of balise groups for SH area.",
          "expected": "The OBU receives the request and checks the train front end position against the Indication supervision limit of the proposed MA."
        },
        {
          "no": 2,
          "action": "The OBU processes the request.",
          "expected": "The OBU rejects the request, keeps the previously received MA, mode profile, and list of balise groups for SH area valid, and sends a message to the RBC indicating rejection (e.g., Train Rejected or specific rejection reason)."
        }
      ]
    },
    {
      "id": "TC-ETC-074-03",
      "title": "Boundary case: Train front end exactly at the Indication supervision limit",
      "covers": [
        "ETC-074"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "Level 2, communication session with RBC established, train running in a mode with valid MA. The train front end position is estimated to be exactly at the Indication supervision limit of the proposed shortened MA.",
      "test_inputs": "RBC sends a 'Request to shorten MA' message containing a proposed shortened MA with an EOA closer to the train than the current EOA.",
      "assumptions": "The requirement states 'in rear' for acceptance and 'in advance' for rejection. The behavior at the exact limit is not explicitly defined in the provided text, but typically 'in rear' implies strictly behind. However, in safety-critical systems, if the limit is the boundary of the supervision area, being exactly at it might be considered 'in rear' or 'in advance' depending on implementation. Assuming 'in rear' means position < limit and 'in advance' means position >= limit, or vice versa. Let's assume the standard interpretation where if the train has not passed the limit, it is in rear. If the train is exactly at the limit, it has not passed it, so it should be accepted. If the requirement implies strict inequality, this test verifies the boundary. Let's assume acceptance if position <= limit (in rear or at) and rejection if position > limit (in advance).",
      "steps": [
        {
          "no": 1,
          "action": "The RBC sends a request to shorten the MA such that the Indication supervision limit is exactly at the current estimated train front end position.",
          "expected": "The OBU evaluates the position. Assuming 'in rear' includes the limit position (or the limit is the start of the new MA's supervision), the OBU accepts the request, adopts the new MA, and informs the RBC of acceptance."
        }
      ]
    }
  ]
}

