      "preconditions": "Level 2, communication session established. Train is in a mode where it can accept a conditional emergency stop (e.g., OS or FS). A valid Movement Authority (MA) is currently active.",
      "test_inputs": "1. Conditional Emergency Stop message with a stop location ahead of the train's current position (min safe front end). 2. A new Movement Authority (MA) message with a valid identifier and parameters.",
      "assumptions": "The RBC is configured to send the emergency stop and subsequently a new MA before revoking the emergency stop.",
      "steps": [
        {
          "no": 1,
          "action": "Send a conditional emergency stop message to the OBU with a stop location that is ahead of the train's current position.",
          "expected": "The OBU accepts the emergency stop message. The train supervision is updated to enforce a stop at the new location with no release speed. The emergency stop is indicated to the driver."
        },
        {
          "no": 2,
          "action": "While the emergency stop is active and not yet revoked, send a new Movement Authority (MA) message to the OBU.",
          "expected": "The OBU rejects the new Movement Authority. The current supervision (emergency stop) remains unchanged. The new MA is not applied."
        }
      ]
    },
    {
      "id": "TC-ETC-086-02",
      "title": "Rejection of new MA after accepted unconditional emergency stop",
      "covers": [
        "ETC-086"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "Level 2, communication session established. Train is in a mode where it can accept an unconditional emergency stop (e.g., OS or FS). A valid Movement Authority (MA) is currently active.",
      "test_inputs": "1. Unconditional Emergency Stop message. 2. A new Movement Authority (MA) message with a valid identifier and parameters.",
      "assumptions": "The RBC is configured to send the emergency stop and subsequently a new MA before revoking the emergency stop.",
      "steps": [
        {
          "no": 1,
          "action": "Send an unconditional emergency stop message to the OBU.",
          "expected": "The OBU accepts the emergency stop message. The train is tripped immediately (emergency brake applied). The emergency stop is indicated to the driver."
        },
        {
          "no": 2,
          "action": "While the emergency stop is active and not yet revoked, send a new Movement Authority (MA) message to the OBU.",
          "expected": "The OBU rejects the new Movement Authority. The train remains in the tripped state. The new MA is not applied."
        }
      ]
    },
    {
      "id": "TC-ETC-086-03",
      "title": "Acceptance of new MA after emergency stop revocation",
      "covers": [
        "ETC-086"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "Level 2, communication session established. Train is in a mode where it can accept a conditional emergency stop. A valid Movement Authority (MA) is currently active.",
      "test_inputs": "1. Conditional Emergency Stop message. 2. Revocation of the emergency stop. 3. A new Movement Authority (MA) message.",
      "assumptions": "The RBC is configured to send the emergency stop, revoke it, and then send a new MA.",
      "steps": [
        {
          "no": 1,
          "action": "Send a conditional emergency stop message to the OBU with a stop location ahead of the train.",
          "expected": "The OBU accepts the emergency stop message. The train supervision is updated to enforce a stop at the new location."
        },
        {
          "no": 2,
          "action": "Send a revocation message for the emergency stop to the OBU.",
