{
  "test_cases": [
    {
      "id": "TC-ETC-109-01",
      "title": "Replacement of stored Level Crossing information with new information of the same identity",
      "covers": [
        "ETC-109"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The OBU is in a mode where Level Crossing information is processed (e.g., FS, OS, LS, or AD). A Level Crossing (LX) information set with a specific identity (e.g., LX_ID_1) is already stored in the OBU memory. The train is approaching the location of this stored LX.",
      "test_inputs": "A new Level Crossing information message with the same identity (LX_ID_1) but different parameters (e.g., different protection status or length) is transmitted to the OBU (via balise or radio, depending on the level).",
      "assumptions": "The new LX information is valid and accepted by the OBU according to other acceptance criteria (e.g., timing, format).",
      "steps": [
        {
          "no": 1,
          "action": "Verify the stored Level Crossing information in the OBU before receiving the new message.",
          "expected": "The OBU holds the initial Level Crossing information with identity LX_ID_1 and its original parameters (e.g., protected status, start location, length)."
        },
        {
          "no": 2,
          "action": "Transmit the new Level Crossing information with the same identity (LX_ID_1) to the OBU.",
          "expected": "The OBU receives the new Level Crossing information."
        },
        {
          "no": 3,
          "action": "Inspect the Level Crossing information stored in the OBU after the reception.",
          "expected": "The stored Level Crossing information for identity LX_ID_1 is replaced by the new information. The old parameters are no longer present, and the new parameters (e.g., updated protection status or length) are active."
        }
      ]
    },
    {
      "id": "TC-ETC-109-02",
      "title": "Independence of Level Crossing information with different identities",
      "covers": [
        "ETC-109"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "The OBU is in a mode where Level Crossing information is processed. Two distinct Level Crossing information sets with different identities (LX_ID_A and LX_ID_B) are stored in the OBU memory.",
      "test_inputs": "A new Level Crossing information message with identity LX_ID_A (different parameters) is transmitted to the OBU. No new information is sent for LX_ID_B.",
      "assumptions": "The new LX information for LX_ID_A is valid and accepted.",
      "steps": [
        {
          "no": 1,
          "action": "Verify the stored Level Crossing information for both identities (LX_ID_A and LX_ID_B) before the update.",
          "expected": "Both LX_ID_A and LX_ID_B are stored with their respective initial parameters."
        },
        {
          "no": 2,
          "action": "Transmit the new Level Crossing information with identity LX_ID_A to the OBU.",
          "expected": "The OBU receives the new Level Crossing information for LX_ID_A."
        },
        {
          "no": 3,
          "action": "Inspect the Level Crossing information stored in the OBU for both identities after the reception.",
          "expected": "The stored information for LX_ID_A is replaced by the new data. The stored information for LX_ID_B remains unchanged, confirming that the replacement is specific to the identity and does not affect other LX information."
        }
      ]
    }
  ]
}

