      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "An active company representative account with a maximum available AAL of AAL2 (password + TOTP bound). A new AAL2-capable authenticator (e.g., passkey) is ready to be bound.",
      "test_inputs": "",
