      "steps": [
        {
          "no": 1,
          "action": "Initiate the binding of the new AAL2 authenticator while authenticated only at AAL1 (e.g., password only, if the system allows partial sessions, or simulate a state where the current session strength is AAL1).",
          "expected": "The system rejects the binding request or prompts for re-authentication at AAL2, as the required AAL is the lower of the account's max (AAL2) and the new authenticator's max (AAL2), which is AAL2."
        },
        {
          "no": 2,
          "action": "Re-authenticate the session at AAL2 (password + TOTP) and initiate the binding of the new AAL2 authenticator.",
          "expected": "The binding process proceeds successfully."
        }
      ]
